/**
 * SP Residency (Shan Poornam Residence) - website data.
 *
 * Single source of truth, both generated by the scripts in `sp-residency/scripts/`:
 *   - public/images/sp-residency/manifest.json      (web assets: path, size, source page, status, approval)
 *   - sp-residency/analysis/project-information.json (facts transcribed from the brochure)
 *
 * Import this module from Server Components only and pass plain props to client components,
 * so the JSON is not shipped to the browser.
 */
import manifest from "../../public/images/sp-residency/manifest.json";
import info from "../../sp-residency/analysis/project-information.json";

export type SpAsset = (typeof manifest.assets)[number];

/** Minimal image props handed to client components. */
export type SpImage = {
  src: string;
  width: number;
  height: number;
  alt: string;
  caption: string;
};

const assetsById = new Map<string, SpAsset>(manifest.assets.map((a) => [a.id, a]));

export function spAsset(id: string): SpAsset {
  const asset = assetsById.get(id);
  if (!asset) throw new Error(`Unknown SP Residency asset "${id}" - rebuild the manifest?`);
  return asset;
}

export function spImage(id: string): SpImage {
  const { src, width, height, alt, caption } = spAsset(id);
  return { src, width, height, alt, caption };
}

export const SP_CREDIT = manifest.assets[0]?.credit ?? "";

export const spProject = {
  name: info.project.name_in_brochure,
  shortName: "SP Residency",
  tagline: info.project.tagline,
  location: "Visalakshipuram, Madurai",
  developer: info.project.developer,
  partner: info.project.collaboration_partner,
  brandStory: info.project.brand_story,
  totalHomes: info.building.total_homes,
  residentialFloors: info.building.residential_floors,
  unitMix: info.building.unit_mix as Record<string, number>,
  amenitiesCount: info.building.amenities_count,
  floorToFloor: info.specifications.structure.floor_to_floor_height_incl_slab,
};

export const spStats = [
  { value: String(info.building.total_homes), label: "Residences" },
  { value: `Stilt + ${info.building.residential_floors}`, label: "Floors" },
  { value: "85%", label: "Carpet to SBU" },
  { value: String(info.building.amenities_count), label: "Amenities" },
];

export type SpUnit = {
  key: string;
  label: string;
  configuration: string;
  carpet: number;
  balcony: number;
  sbu: number;
  facing: string;
  rooms: { name: string; dims: string }[];
  plan: SpImage;
};

const UNIT_KEYS = ["A", "B", "C", "D", "E", "F"] as const;

export const spUnits: SpUnit[] = UNIT_KEYS.map((key) => {
  const u = info.units[key];
  return {
    key,
    label: `Type ${key}`,
    configuration: u.configuration,
    carpet: u.carpet_area_sqft,
    balcony: u.exclusive_balcony_area_sqft,
    sbu: u.super_built_up_area_sqft,
    facing: u.vastu.label,
    rooms: u.rooms.map((r) => ({ name: r.name, dims: r.dimensions_as_printed })),
    plan: spImage(`sp-plan-${key.toLowerCase()}`),
  };
});

